android.extraProguardRules:
# === RADPRO custom keep rules (R8) ===
# React Native Firebase bridge (reflection-based module registration)
-keep class io.invertase.firebase.** { *; }
-dontwarn io.invertase.firebase.**
# Firebase SDK
-keep class com.google.firebase.** { *; }
-dontwarn com.google.firebase.**
# ML Kit face detection (vision-camera-face-detector)
-keep class com.google.mlkit.** { *; }
-dontwarn com.google.mlkit.**
# MapLibre
-keep class org.maplibre.** { *; }
-dontwarn org.maplibre.**
# react-native-vision-camera
-keep class com.mrousavy.camera.** { *; }
# @react-native-picker/picker
-keep class com.reactnativecommunity.picker.** { *; }
